def min_distance(p1, p2):
    return min(abs(p1[0] - p2[0]), abs(p1[1] - p2[1]))

def min_max_distance(p1, p2):
    x_dist = min(p1[0] + p1[1] + 1, p2[0] + p2[1] + 1) - max(p1[0] - p1[1] - 1, p2[0] - p2[1] - 1)
    y_dist = min(p1[0] - p1[1] + 1, p2[0] - p2[1] + 1) - max(p1[0] + p1[1] + 1, p2[0] + p2[1] + 1)
    return x_dist if x_dist < y_dist else y_dist

def find_seat(k, pairs):
    seats = set([pair for pair in pairs])
    max_num = 0
    for p in seats:
        x, y = p
        operations = 0
        for pair_u in pairs:
            if pair_u in seats:
                first_d = min_distance(pair_u, (x, y)) + operations
                second_d = min_max_distance(pair_u, (x, y))
                if first_d < second_d:
                    x, y = pair_u
                    operations += 1
            else:
                if operations:
                    break
        else:
            yield x, y
    max_num += 1

