    ar_prev = -1
    ans = 0

    for pattern in patterns:
        words = list(pattern)
        word_count = Counter(words)

        if len(word_count) == 1:
            if all(word in S for word in word_count):
                # If all words are in S and no prefix forms a match
                ans += 1
        else:
            if all(ar_prev >= len(repr(w)) for w in word_count.values()):
                # Continue to find pre-requisite pattern in S
                continue
            else:
                arr = [0] * len(pattern)
                ar, ar_prev, correct = 0, -1, 0
