from collections import deque

def rotate_matrix(matrix, direction):
    R, L, D, U, I, C = direction
    matrix_copy = [row.copy() for row in zip(*matrix)]
    n = len(matrix)

    if R:
        matrix_copy = list(zip(*matrix_copy))
    elif L:
        matrix_copy = list(zip(*matrix_copy))[::-1]
    elif D:
        matrix_copy = list(zip(*matrix_copy[:0:-1]))
    elif U:
        matrix_copy = list(zip(*matrix_copy[::-1]))
    elif I:
        for i in range(n):
            deque(matrix_copy[i])[:] = deque([j for j in matrix[i]][::-1])
    elif C:
        for i in range(n):
            deque(matrix[i])[:] = deque([j for j in matrix[i]])[::-1]

    rotated_matrix = list(zip(*matrix_copy))
    return rotated_matrix

def shift_up(matrix, up_shift):
    up_shift = min(up_shift, len(matrix[0]))
    new_matrix = [row[up_shift:] + row[:up_shift] for row in matrix]
    n = len(matrix)
    for i in range(n):
        new_matrix[i] = new_matrix[i][::-1]
    for i in range(n):
        new_matrix[i] = new_matrix[i][up_shift:] + new_matrix[i][:up_shift]

    return new_matrix

def inverse_permutation(perm):
    inv = [0] * len(perm)
    d = {}
    for i, val in enumerate(perm):
        d[val] = i
    for i, val in enumerate(perm):
        inv[d[i]] = val

    return inv

def final_matrix(matrix, operations, n):
    for op in operations:
        dr = op[0].lower() == 'd'
        dl = op[0].lower() == 'l'
        order = op[0]
        if dr:
            matrix = rotate_matrix(matrix, ["R", "D"])
        elif dl:
            matrix = rotate_matrix(matrix, ["L", "D"])
        elif op[1:].lower() == "i":
            matrix = rotate_matrix(matrix, ["I", "D", "R"])
        elif op[1:].lower() == "c":
            matrix = rotate_matrix(matrix, ["C", "R", "U"])
        else:
            shift = int(op[1:])
            if 'd' in order: shift = len(matrix[0]) - shift
            if 'l' in order: shift = len(matrix) - shift
            matrix = shift_up(matrix, shift)
    return matrix

