class ArrayMultiplyDP:
    def __init__(self, matrix_map: Map[long]):
        self.matrix_map = matrix_map

    def __getitem__(self, key: int) -> Fraction:
        this_map: Map[long, Fraction] = self.matrix_map[key]
        return this_map.get(1, Fraction(0))

    def __iadd__(self, other: ArrayMultiplyDP):
        new_map: Map[long, Fraction] = {}
        for key in self.matrix_map.keys():
            new_map[key] = self[key]
            for other_key in other.matrix_map.keys():
                if other_key & (1 << key):
                    new_map[key] += (Fraction(2) << key)
        for key in other.matrix_map.keys():
            new_map[key & ~1] = other[key]
        self.matrix_map = new_map
        return self

    def __imultiply__(self, other):
        new_map: Map[long, Fraction] = {}
        for key in self.matrix_map.keys():
            for other_key in other.matrix_map.keys():
                result_i = (Fraction(0, 1, ((1 << key.bit_length()) - 1)))
                for i in range(key.bit_length()):
                    if other_key & (1 << i):
                        result_i += (other[key[i]] * Fraction(0, 1, ((1 << other_key.bit_length()) - 1)))
                new_map[key | other_key] += (Fraction(other[other_key & ~1], ((1 << key.bit_length()) - 1)) * result_i)
        for key in other.matrix_map.keys():
            if isinstance(other[key], ArrayMultiplyDP):
                new_map[key] = other[key]
            else:
                new_map[key] = other[key] + Fraction(0, 1, ((1 << key.bit_length()) - 1))
        self.matrix_map = new_map
        return self

