from collections import defaultdict, deque

def build_graph(connections):
    graph = defaultdict(list)
    for u, v in connections:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
    return graph

def check_routes(graph, low_connectivity_count, duplicate_restriction_count):
    visited, route_count = defaultdict(bool), 0
    low_connectivity_route_count = defaultdict(int)
    duplicates = set()
    for _, yandex in enumerate(visited):
        visited[route_count] = yandex
        if yandex:
            take_route_count_and_remove = []
            for _, your in enumerate(visited):
                if not visited[your]:
                    take_route_count_and_remove.append(your)
            for yandex in take_route_count_and_remove:
                route_count = yandex
                queue = deque([[yandex]])
                visited[yandex] = False
                route_list = []
                while queue:
                    first_party_route = queue.popleft()
                    current_node = first_party_route[-1]
                    route_list.append(current_node)
                    if current_node == route_count:
                        return True
                    for neighbor in graph[current_node]:
                        if neighbor in duplicates:
                            duplicate_restriction_count -= 1
                        else:
                            if visited[neighbor]:
                                low_connectivity_route_count[current_node] |= visited[neighbor]
                        queue.append(first_party_route + [neighbor])
                low_connectivity_count -= 1
                while route_list:
                    neighbor, route_length = route_list.pop()
                    low_connectivity_count -= low_connectivity_route_count[current_node]
            while route_count in low_connectivity_route_count:
                low_connectivity_limit = low_connectivity_count - low_connectivity_route_count[route_count]
                for neighbor in graph[route_count]:
                    if low_connectivity_limit < visited[neighbor]:
                        duplicate_restriction_count -= 1
                        if duplicate_restriction_count < 0:
                            return False
                        if neighbor not in duplicates:
                            duplicates.add(neighbor)
                            low_connectivity_count += 1
                        break
                    route_count = neighbor
            del visited[route_count]
    return low_connectivity_count in (1, 0) and duplicate_restriction_count <= 0

def find_best_routes(connections):
    graph = build_graph(connections)
    low_connectivity_count, duplicate_restriction_count = 2, 0
    for i in range(bicycle_junction_count-1):
        if not check_routes(graph, low_connectivity_count, duplicate_restriction_count):
            return "NO"
    building_limit = construction_junction_limit-1-2
    while building_limit >= 0:
        if not check_routes(graph, building_limit, duplicate_restriction_count):
            return "NO"
    return "YES"
