def cyclic_shift_left(matrix, n, offset):
    for row in matrix:
        for i in range(n):
            row[i], row[(i + offset) % n] = row[(i + offset) % n], row[i]

def cyclic_shift_right(matrix, n, offset):
    for row in matrix:
        for i in range(n):
            row[i], row[(i + offset) % n] = row[(i + offset) % n], row[i]

def inv_permutation(n, perm):
    inv_perm = [0] * n
    for i in range(n):
        inv_perm[perm[i] - 1] = i + 1
    return inv_perm

def process_operations(operations, matrix, n, perm_mod):
    for op in operations:
        if op == 'R':
            cyclic_shift_right(matrix, n, 1)
        elif op == 'L':
            cyclic_shift_left(matrix, n, 1)
        elif op == 'D':
            cyclic_shift_right(matrix, n, 1)
        elif op == 'U':
            cyclic_shift_left(matrix, n, 1)
        elif op == 'I':
            perm = map(lambda x: x - 1, perm_mod)
            inv = inv_permutation(n, perm)
            perm = map(lambda x: x + 1, inv)
            perm_mod = list(perm)
        elif op == 'C':
            perm = map(lambda x: x - 1, perm_mod)
            inv = inv_permutation(n, perm)
            perm = map(lambda x: x + 1, inv)
            perm_mod = list(perm)

