from bisect import *
from itertools import accumulate

def update_tree(tree, indices, tree_size, index, value):
    index += tree_size // 2
    tree[index] = value
    while index > 0:
        left_child = index * 2 + 1
        right_child = index * 2 + 2
        left = tree[left_child]
        right = tree[right_child]
        if left >= tree_size:
            tree[index] = right
        elif right >= tree_size:
            tree[index] = left
        else:
            tree[index] = left if left >= value else right
        index -= 1

def query_tree_sum(tree, tree_size, query_left, query_right):
    result = 0
    query_left += tree_size // 2
    query_right += tree_size // 2
    left = query_left
    right = query_right
    while left <= right:
        if left % 2 == 1:
            result += tree[left]
            left += 1
        if right % 2 == 0:
            result += tree[right]
            right -= 1
        left //= 2
        right //= 2
    return result

class SegmentTree:
    def __init__(self, size, initial_value=0):
        self.tree = [initial_value] * (2 * size)
        self.tree_size = size

    def get_val_at_index(self, index):
        return query_tree_sum(self.tree, self.tree_size, index, index)

    def get_interval_sum(self, start, end):
        return query_tree_sum(self.tree, self.tree_size, start + self.tree_size, end + self.tree_size)

    def init_value(self):
        return 0

    def update(self, start, end, value):
        update_tree(self.tree, self.tree_size, len(self.tree), start, value)
        update_tree(self.tree, self.tree_size, len(self.tree), end + 1, self.value)

class Node:
    def __init__(self, start, end, index):
        self.left = self.right = None
        self.val = 0
        self.start = start
        self.end = end
        self.index = index

def build_tree(bst, start, end):
    if start > end:
        return None
    query_start = (start + end) // 2
    node = Node(start, end, bst.query(query_start))
    if node.start > node.end:
        node.right = build_tree(bst, start, query_start)
    else:
        node.left = build_tree(bst, query_start, end)
    return node

