def apply_operation(op, matrix):
    # Update the rows and columns as per the operation
    n = len(matrix)
    if op == 'R':
        temp = [matrix[i][j-2] for j in range(1, n+1)]  # Shift columns to the right
    elif op == 'L':
        temp = [matrix[i][j % n] for j in range(n)]  # Shift columns to the left
    elif op == 'D':
        temp = [matrix[i-2][j] for i in range(1, n+1)]  # Shift rows down
    elif op == 'U':
        temp = [matrix[i % n][j] for i in range(n)]  # Shift rows up
    elif op == 'I':
        inv_matrix = inverse_permutation([row for row in matrix])
        for i in range(n):
            temp[i] = inv_matrix[n - matrix[i].index(i + 1)]
    elif op == 'C':
        inv_matrix = inverse_permutation([row for row in zip(*matrix)])
        for i in range(n):
            temp[i] = inv_matrix[i][n - matrix[i].index(i + 1)]

    return temp

