def is_route_possible(n, m, roads):
    # Build adjacency list for roads
    graph = defaultdict(list)
    for u, v in roads:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    # Check if it's possible to have a zero point route
    if len(graph[roads[0]]) > 3:
        return "NO"
    if len(graph[roads[1]]) > 2 or len(graph[roads[2]]) > 2:
        return "NO"

    # Remove roads from graph
    for u, v in roads:
        for uu in graph[u-1]:
            for vv in graph[v-1]:
                if uu == u or vv == v:
                    graph[u-1].remove(uu)
                    graph[v-1].remove(vv)

    # Check if it's possible to have non-zero point routes
    vertices = set()
    for u in graph:
        for v in graph[u]:
            if u != v:
                vertices.add(u)
                vertices.add(v)

    if len(vertices) < 3:
        return "NO"
    for u in graph:
        if len(graph[u]) < len(graph[0]):
            return "NO"

    if max(len(graph[u]) for u in graph) == 1:
        return "NO"

    for u in graph:
        if len(graph[u]) == 1:
            return "NO"

    return "YES"

