def find_rotatable_base(n, x):
    max_base = -1

    for base in range(2, x):
        current_base = base
        while len(str(current_base)) > n:
            current_base = int(str(current_base) + str(current_base)[-1]) % current_base
            if current_base != 1:
                break
        else:
            if len(str(current_base)) <= n and str(current_base)[0] == '0':
