from heapq import heappop, heappush

def find_shortest_path(n, bridges, main_hotels):
    adj = defaultdict(list)
    visited = set()
    m, k = len(bridges) + 1, set(main_hotels)

    for a, b in bridges:
        adj[a].append(b)
        adj[b].append(a)

    result = {}

    for source in range(1, n + 1):
        for destination in main_hotels:
            if destination in visited:
                continue

            q = []
            distances = {(destination, source): 0, (source, destination): 0}

            visited.add(destination)
            heappush(q, (0, source, destination, (destination, source)))

            while q:
                _, current_node, distance, (u, v) = heappop(q)

                if u in visited:
                    continue

                visited.add(u)

                for neighbor in adj[u]:
                    if neighbor not in visited:
                        distance_to_destination = max(distance, distances[neighbor, u] + 1)
                        new_path = (neighbor, distance_to_destination, (v, u, 1 - distance_to_destination))
                        distances[(neighbor, u)] = distance_to_destination

                        heappush(q, new_path)

                        if neighbor == destination:
                            if result.get(neighbor) is None or result[neighbor]["time"] > distance_to_destination:
                                result[neighbor] = {"time": distance_to_destination, "path": new_path}

    return result

