import sys

class Edge:
    def __init__(self, x, y):
        self.x = x
        self.y = y

class Node:
    def __init__(self, id):
        self.id = id
        self.parent = None

class Tree:
    def __init__(self, n):
        self.root = Node(-1)
        self.nodes = [self.root]
        self.edges = []
        for i in range(1, n):
            self.nodes.append(Node(i))
        self.n = n

    def add_edge(self, e1, e2):
        e1, e2 = max(e1, e2), min(e1, e2)
        e1_index = self.get_node_index(e1)
        e2_index = self.get_node_index(e2)
        e1_index.next, e2_index.next = e2_index, e1_index

    def dfs(self, n, parent):
        if n:
            self.nodes[n].parent = parent
            for i in n.adjacent:
                if i != parent and self.nodes[i].parent == n:
                    self.dfs(i, n.id)

    def get_node_index(self, n):
        while n != self.root.id:
            n = self.nodes[n].parent

        return n
