            row_perm = inverse_permutation(row_perm)
        elif op == 'L':
            col_perm = inverse_permutation(col_perm)
        elif op == 'D':
            row_perm = row_perm[-1::-1]
        elif op == 'U':
            row_perm = row_perm[1::]
        elif op == 'I':
            row_perm = row_perm[::-1]
        elif op == 'C':
            col_perm = col_perm[-1::-1]
