import bisect

def array_query_handler(mapping: dict, arr: list, limit: int) -> set:
    maxVal = 0
    res = set()
    if '?' not in mapping:
        return set(range(1, limit+1))

    # Rescoring before conversion to set
    for num in arr:
        if num & limit != num:
            limit = max(limit, num+limit)

    for i in range(1, len(mapping)):
        if mapping[i]:
            nums = mapping[i]
            for num in nums:
                curMax = maxVal ^ num
                curBound = bisect.bisect_right(mapping[num] + [limit], maxVal, lo = i+1, hi = len(mapping))
                res.update(range(min(i+1, curBound), curBound, -1))
                maxVal = max(maxVal, curMax)
    return res

def find_subarrays_with_bitwise_or(a, x, limit):
    mapping = {i : [] for i in range(x+1)}
    mapping[0].extend(range(1, len(a)+1))

    for i in range(x+1):
        if a[i] & limit != a[i]:
            limit = x+limit
        mapping[a[i]].append(limit)

    return array_query_handler(mapping, a, limit)

