def max_net_coins(N: int, L: int, R: int, cans: List[int], values: List[int], bs: List[int]) -> int:
    global_cost = 0

    # Local payer S
    S = defaultdict(int)
    for i in range(N):
        S[i] += values[i]

    # Global payer Z
    cost_per_axis = {0: 0}
    optimal_x_situation = 0

    for i in range(N):
        flipped_cans = L <= cans[i] <= R
        removed_cost = 1 + (R-cans[i]) * bs[i] if flipped_cans else 0
        if S[i] > cost_per_axis.get(cans[i], 0) + removed_cost:
            continue
        for x in range(0, N):
            cd = (cans[i] - x, bs[i] * (1 + 1 if i == x else -1))
            if cd in cost_per_axis:
                if local_cost := cost_per_axis[cd] - S[i] + removed_cost:
                    cost_per_axis[cd] = local_cost
                    optimal_x_situation = max(optimal_x_situation, x)
                    break
            else:
                cost_per_axis[cd] = removed_cost + S[i]
                if removed_cost < 0:
                    optimal_x_situation = max(optimal_x_situation, x)
                break
        else:
            continue
        for fallback_local_cost in S.values():
            cd = (0, fallback_local_cost)
            if cd in cost_per_axis:
                cost_per_axis[cd] = max(cost_per_axis[cd], cost_per_axis[cd] - S[i] + removed_cost)
                S[cd] = max(S[cd], fallback_local_cost)
            else:
                S[cd] = fallback_local_cost
                cost_per_axis[cd] = removed_cost + fallback_local_cost
    total_coins = 0
    return sum(cost_per_axis[cd] - S[i] for i, cd in enumerate(sorted(cost_per_axis))), sum(values) - total_coins

