import math

def find_largest_base(n, x):
    if n <= 1: 
        return -1
    if n == 2: 
        if x % 2 == 0:
            return x // 2
        else:
            return -1

    def validate_base(base):
        rotated_number = base ** n
        for i in range(1, n+1):
            if rotated_number % i != i:
                return False
        return True

    for b in range(11, int(math.sqrt(x*2)) + 1, 2): # start from 11 as 1 is trivial and we avoid even no's due to log operation
        if validate_base(b):
            return b
    return -1

