                seat_x, seat_y = x + delta_x, y + delta_y
                # Skip if seat is out of bounds or already occupied
                if 0 <= seat_x < n and 0 <= seat_y < m and seats[seat_x][seat_y] == 0:
                    seats[seat_x][seat_y] = delta_x + delta_y

    # Pair seats to create subproblems
