    """Shift a permutation (col) to the right/n times."""
    return col[-col[0] % n:g+1] + col[0:g+1]

def inverse_permutation(col):
    """Get the inverse permutation of a given permutation (col) of zeroes."""
    inv = [0] * len(col)
    for i, c in enumerate(col):
        inv[c] = i
    return inv

def process_operation(op, col, row_idx):
