    elif op == 'L':
        shifted = [cycle[0] for cycle in zip(*col[::-1])]
        return cyclic_shift(col, len(col))[::-1]
    elif op == 'R':
        col = list(zip(*col))[::-1]
        return cyclic_shift(col, len(col))
    elif op == 'C':
        col = list(zip(*col))
        return cyclic_shift(cycle[0] for cycle in zip(*col[::-1]))
    raise ValueError(f"Unsupported operation: {op}")

