from itertools import permutations

def rotate_matrix(matrix, direction):
    n = len(matrix)
    if direction == 'R':
        for _ in range(n):
            for j in range(n // 2):
                temp = matrix[j][j]
                matrix[j][j] = matrix[n - j - 1][j]
                matrix[n - j - 1][j] = matrix[n - j - 1][n - j - 1]
                matrix[n - j - 1][n - j - 1] = matrix[j][n - j - 1]
                matrix[j][n - j - 1] = temp
    elif direction == 'L':
        for _ in range(n):
            for j in range(n // 2):
                temp = matrix[j][n - j - 1]
                matrix[j][n - j - 1] = matrix[n - j - 1][n - j - 1]
                matrix[n - j - 1][n - j - 1] = matrix[n - j - 1][j]
                matrix[n - j - 1][j] = temp
    elif direction == 'U':
        for _ in range(n):
            for j in range(n // 2):
                temp = matrix[n - j - 1][j]
                matrix[n - j - 1][j] = matrix[n - j - 1][n - j - 1]
                matrix[n - j - 1][n - j - 1] = matrix[j][n - j - 1]
                matrix[j][n - j - 1] = temp
    elif direction == 'D':
        for _ in range(n):
            for j in range(n // 2):
                temp = matrix[j][n - j - 1]
                matrix[j][n - j - 1] = matrix[n - j - 1][n - j - 1]
                matrix[n - j - 1][n - j - 1] = matrix[n - j - 1][j]
                matrix[n - j - 1][j] = temp

def is_permutation(matrix):
    return all(p == list(range(1, len(matrix) + 1)) for p in zip(*matrix))

def apply_operations(matrix, operations_str):
    operations = [('D', 1), ('U', 1), ('R', 2), ('L', 2), ('I', 3), ('C', 4)]
    order = {'D': 1, 'U': 1, 'R': 2, 'L': 2, 'I': 3, 'C': 4}
    for op, repeat in {op: ord(op) for op in operations_str}.items():
        for _ in range(repeat):
            for side, n in order.items():
                for i in range(n):
                    rotate_matrix(matrix, side)
            if is_permutation(matrix):
                break
    return matrix

