def rotate_vector(vector):
    return [vector[-1]] + vector[:-1]

def move_vector(vector, direction):
    vector = rotate_vector(vector)
    if direction == 'R':
        vector = rotate_vector(vector)
    elif direction == 'L':
        vector = rotate_vector(vector)
    vector = rotate_vector(vector)
    return vector

def reflect_matrix(matrix, column):
    new_matrix = []
    for row in matrix:
        new_row = []
        for j in column:
            new_row.append(row[j-1])
        new_matrix.append(new_row)
    return new_matrix

def reverse_permutation(perm):
    return ''.join([str((int(c) + int(second_half(mod % len(second_half), len(second_half)))) % len(second_half)) for c in perm])

def process_operations(matrix, operations):
    for direction in operations:
        if direction == 'L' or direction == 'R':
            matrix = move_vector(matrix, direction)
        elif direction == 'D' or direction == 'U':
            matrix = reflect_matrix(matrix, [i-1 for i in range(len(matrix))])
        elif direction == 'I':
            matrix = [[int(a)-1 for a in row] for row in matrix]  # Convert to natural numbers
            for i, row in enumerate(matrix):
                matrix[i] = reverse_permutation(list(enumerate(row)))
            matrix = [[int(a)+1 for a in row] for row in matrix]  # Convert back to natural numbers
        elif direction == 'C':
            matrix = reflect_matrix(matrix, [i for i in range(len(matrix[0]))])
    return matrix

