            for i in range(x, 10000 + 1):
                for j in range(y, 10000 + 1):
                    lx, ly = prev_intersect[i], prev_intersect[j]
                    dx = abs(cx - lx) // 2
                    dy = abs(cy - ly) // 2
                    if dx > ((i-x) + (j-y)) // 2 and dy > ((i-x) + (j-y)) // 2 and (lx - x) % 2 == cx % 2 and (ly - y) % 2 == cy % 2:
                        if lx == x:
                            new_intersect.append((lx + 1, ly))
                        else:
                            new_intersect.append((lx, ly + 1))
            prev_intersect = new_intersect
            count += len(new_intersect) - 1
            max_num = max(max_num, count + 1)
        return max_num

