def find_base(n, x):
    upper_base = x
    lower_base = 2
    if x < 10:
        return -1
    if x >= n * 25:
        return 25 * 10 ** (n // 50)
    for base in range(upper_base, lower_base - 1, -1):
        check_base = n * 10 ** (base - 1)
        for i in range(1, base):
            result = check_base * i
            rotated = int(str(result)[-1:]) * (10 ** (base - 1)) + result[:-base + 1]
            if rotated in str(result):
                return base
    return -1

