from collections import deque

def is_yalalovichik(s):
    # Check if the string has enough length to form all substrings
    if len(s) < 2 * len(set(s)):
        return False

    n = len(s)
    dp = [1] * n
    for i in range(1, n):
        m = (i + 1) // 2
        for j in range(m):
            dp[i] |= (dp[i-m+j] & dp[j+i-m])
    return dp[n-1]

def count_yalalovichik_substrings(s):
    n = len(s)
    dp = [1] * (n+1)
    for i in range(1, n+1):
        for j in range(1, i):
            dp[i] += (is_yalalovichik(s[j-1:i]) * dp[i-1-j] + is_yalalovichik(s[:j]+s[i:]) * dp[i-j])
    return dp[-1]

T = int(input())
for _ in range(T):
    n = int(input())
    s = input().strip()
    print(count_yalalovichik_substrings(s))
