from collections import defaultdict

def min_time_to_nearest_main_hotel(hotels, queries):
    if len(hotels) == 2:
        return 0

    graph = defaultdict(list)
    for u, v in hotels:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    times = [float('inf')] * len(hotels)
    visited = [False] * len(hotels)

    def get_min_path(to_go_from):
        maze = [float('inf')] * len(times)
        maze[to_go_from] = 0
        for i in range(len(times)):
            for j in range(len(times)):
                if maze[i] != float('inf') and j not in graph[i]:
                    maze[j] = min(maze[i] + 1, maze[j])
        return maze

    for m in queries:
        times[m-1] = min(get_min_path(m-1))
    return [min(times)] * len(queries)

# Example usage
hotels = [[1, 2], [2, 3], [1, 3]]
queries = [1, 2, 3]
result = min_time_to_nearest_main_hotel(hotels, queries)
